def process_orders(orders):
    if len(orders) == 0:
        return []
    out = []
    for order in orders:
        amount = order.get('amount', 0)
        payment = order.get('payment')
        if amount > 0 and hasattr(payment, 'validate') and payment.validate(order):
            out.append(order.get('id'))
    return out
